const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const panel=document.createElement('section');panel.className='composer opportunity-workspace';panel.id='opportunity-workspace';panel.innerHTML=`<div class="composer-top"><div><div class="eyebrow">OPPORTUNITY INTELLIGENCE</div><h2>Your next opportunity.<br><span>With the evidence attached.</span></h2></div><span class="small-tag">JOBS + HACKATHONS</span></div><p>Find real listings. Check each requirement. Keep unknown eligibility separate from qualified results.</p><form id="opp-form"><div class="research-actions"><label for="opp-kind">I’m looking for</label><select id="opp-kind"><option value="jobs">Remote jobs</option><option value="hackathons">Hackathons</option></select></div><label for="opp-query">Describe your requirements · English / Hindi</label><textarea id="opp-query" rows="3" maxlength="2000" required>Find paid remote jobs available to applicants based in India.</textarea><div class="research-actions"><button class="primary" id="opp-start">Find opportunities ↗</button><button class="secondary" type="button" id="opp-history">Recent runs</button></div></form><div id="opp-progress" role="status" aria-live="polite"></div><div id="opp-result"></div>`;document.querySelector('.composer').after(panel);
let job=null,timer=null,active=null,filter='qualified';
async function api(path,options){const r=await fetch(path,options),j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j}
function rows(){if(!job)return;const q=document.querySelector('#opp-search').value.toLowerCase();const list=job.rows.filter(r=>(filter==='all'||r.status===filter)&&(r.title+' '+JSON.stringify(r.fields)).toLowerCase().includes(q));const holder=document.querySelector('#opp-table');holder.innerHTML=list.length?`<div class="table-scroll"><table><thead><tr><th>OPPORTUNITY</th><th>ELIGIBILITY / LOCATION</th><th>DATES / SALARY</th><th>STATUS</th><th>EVIDENCE</th></tr></thead><tbody>${list.map(r=>`<tr><td><strong>${E(r.title)}</strong><small>${E(r.fields.organisation||'')}</small><a href="${E(r.url)}" target="_blank" rel="noreferrer">${r.kind==='jobs'?'Remotive listing':'Original source'} ↗</a></td><td>${E(r.fields.geography||'Not stated')}<small>${E(r.fields.mode||'Mode unknown')}</small></td><td>${E(r.kind==='jobs'?(r.fields.salary||'Salary not stated'):(r.fields.registration_deadline?'Registration: '+r.fields.registration_deadline:r.fields.submission_deadline?'Submission: '+r.fields.submission_deadline:'Registration deadline unknown'))}</td><td><span class="pill ${r.status==='qualified'?'merged':'conflict'}">${E(r.status.replaceAll('_',' '))}</span></td><td><button class="secondary" data-opp-row="${E(r.id)}">Inspect ${r.checks.length} checks</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No matching rows in this category. Unknowns are not promoted to qualified.</div>';holder.querySelectorAll('[data-opp-row]').forEach(b=>b.onclick=()=>inspect(b.dataset.oppRow));document.querySelectorAll('[data-opp-export]').forEach(a=>a.href='/api/opportunities/'+job.id+'?export='+a.dataset.oppExport+'&q='+encodeURIComponent(q));document.querySelector('#opp-count').textContent=`${list.length} matching / ${job.rows.length} collected · CSV categories use this text filter and include every matching row.`}
function inspect(id){const r=job.rows.find(x=>x.id===id),p=document.querySelector('#opp-evidence');p.innerHTML=`<h3>${E(r.title)} — qualification evidence</h3><p>Checked ${E(r.checked_at||'pending')}. Source statements are not a guarantee of acceptance.</p>`+r.checks.map(c=>`<article class="source-card"><span class="pill ${c.status==='PASS'?'merged':'conflict'}">${E(c.status)}</span> <strong>${E(c.condition)}</strong><p>${E(c.reason)}</p>${c.evidence_ids.map(id=>{const e=r.evidence.find(e=>e.id===id);return `<details><summary>${E(e.field)} · source evidence</summary><p>${E(e.value)}</p><blockquote>${E(e.locator)}</blockquote><a href="${E(e.source_url)}" target="_blank" rel="noreferrer">Source ↗</a><small>Retrieved ${E(e.retrieved_at)}</small></details>`}).join('')}</article>`).join('');p.scrollIntoView({behavior:'smooth',block:'start'})}
function render(j){job=j;const pending=j.status==='running';document.querySelector('#opp-start').disabled=pending;document.querySelector('#opp-progress').textContent=j.status+' · '+j.stage;if(pending&&!j.rows.length)return;
const counts=j.counts||{};document.querySelector('#opp-result').innerHTML=`<details open><summary>Interpreted requirements</summary><pre>${E(JSON.stringify(j.plan,null,2))}</pre></details><p>${E(j.attribution||'')}</p><p class="research-note">${E(j.notice||'Collection in progress. Checks are applied when retrieval completes.')}</p><div class="research-actions">${['qualified','needs_verification','excluded','all'].map(s=>`<button class="secondary" data-opp-status="${s}" aria-pressed="${s===filter}">${E(s.replaceAll('_',' '))} ${s==='all'?j.rows.length:counts[s]??'…'}</button>`).join('')}</div><label for="opp-search">Search these results</label><input id="opp-search" placeholder="Title, organisation, location…"><div id="opp-table"></div><p id="opp-count"></p>${!pending?`<div class="research-actions">${['qualified','needs_verification','excluded','evidence','duplicates','gaps'].map(k=>`<a data-opp-export="${k}" class="${k==='qualified'?'dark-button':'secondary'}" href="/api/opportunities/${j.id}?export=${k}">↓ ${E(k.replaceAll('_',' '))}.csv</a>`).join('')}</div>`:''}<div id="opp-evidence"></div><details><summary>Collection gaps · ${j.gaps.length}; duplicate links · ${j.duplicates.length}</summary>${j.gaps.map(g=>`<p>${E(g.source||'Scope')}: ${E(g.reason)}</p>`).join('')}<pre>${E(JSON.stringify(j.duplicates,null,2))}</pre></details>`;document.querySelector('#opp-search').oninput=rows;document.querySelectorAll('[data-opp-status]').forEach(b=>b.onclick=()=>{filter=b.dataset.oppStatus;document.querySelectorAll('[data-opp-status]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));rows()});rows();}
async function poll(id){try{const j=await api('/api/opportunities/'+id);if(id!==active)return;render(j);if(j.status==='running')timer=setTimeout(()=>poll(id),2000)}catch(ex){document.querySelector('#opp-progress').textContent=ex.message;document.querySelector('#opp-start').disabled=false}}
document.querySelector('#opp-form').onsubmit=async ev=>{ev.preventDefault();clearTimeout(timer);document.querySelector('#opp-start').disabled=true;document.querySelector('#opp-result').innerHTML='';try{const j=await api('/api/opportunities',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:document.querySelector('#opp-query').value,kind:document.querySelector('#opp-kind').value})});active=j.id;localStorage.setItem('eklist-opportunity',active);filter='qualified';poll(active)}catch(ex){document.querySelector('#opp-progress').textContent=ex.message;document.querySelector('#opp-start').disabled=false}};
document.querySelector('#opp-kind').onchange=ev=>{document.querySelector('#opp-query').value=ev.target.value==='jobs'?'Find paid remote jobs available to applicants based in India.':'Find online hackathons for college students based in India, age 20, with registration deadlines in the next 30 days.'};
document.querySelector('#opp-history').onclick=async()=>{try{clearTimeout(timer);active=null;const d=await api('/api/opportunities');document.querySelector('#opp-result').innerHTML=d.jobs.map(j=>`<p><button class="secondary" data-opp-job="${j.id}">${E(j.query)} · ${E(j.status)}</button></p>`).join('');document.querySelectorAll('[data-opp-job]').forEach(b=>b.onclick=()=>{active=b.dataset.oppJob;poll(active)})}catch(ex){document.querySelector('#opp-progress').textContent=ex.message}};
const previous=localStorage.getItem('eklist-opportunity');if(previous){active=previous;poll(active)}
